SOZLUK = ["kilim", "kilim yikama", "bakir cezve", "kese", "recel", "kestane sekeri"]
ESANLAM = {"halicik": "kilim", "cezve": "bakir cezve", "marmelat": "recel"}


def uzaklik(a, b):
    onceki = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        simdiki = [i]
        for j, cb in enumerate(b, 1):
            simdiki.append(min(onceki[j] + 1, simdiki[j - 1] + 1,
                               onceki[j - 1] + (ca != cb)))
        onceki = simdiki
    return onceki[-1]


def coz(sorgu):
    s = sorgu.strip().lower()
    if s in SOZLUK:
        return ("tam", s)
    if s in ESANLAM:
        return ("esanlam", ESANLAM[s])
    en_iyi, en_yakin = None, 99
    for t in SOZLUK:
        d = uzaklik(s, t)
        if d < en_yakin or (d == en_yakin and en_iyi is not None and t < en_iyi):
            en_yakin, en_iyi = d, t
    esik = 1 if len(s) <= 4 else 2
    if en_yakin <= esik:
        return ("duzeltildi", en_iyi)
    return ("sifir", None)


