from datetime import date, timedelta

TATIL = {date(2026, 4, 23), date(2026, 5, 1)}
KESIM_SAATI = 14          # bu saatten sonra gelen siparis ertesi is gunu hazirlanir


def is_gunu_mu(g):
    return g.weekday() < 5 and g not in TATIL


def ileri_is_gunu(g, adet):
    while adet > 0:
        g += timedelta(days=1)
        if is_gunu_mu(g):
            adet -= 1
    return g


def vaat(siparis_gun, saat, hazirlik, transit):
    g = siparis_gun
    if saat >= KESIM_SAATI or not is_gunu_mu(g):
        g = ileri_is_gunu(g, 1)
    kargo = ileri_is_gunu(g, hazirlik - 1) if hazirlik > 0 else g
    return ileri_is_gunu(kargo, transit)


