import math

KAPASITE = 70.0      # sunucu basina istek/s
SAAT_UCRET = 38.0    # sunucu basina saatlik maliyet (senaryo)
MU = 45.0            # bekleme odasindan saniyede kabul edilen kisi


def sunucu_sayisi(istek_s, isabet):
    return max(1, math.ceil(round(istek_s * (1 - isabet) / KAPASITE, 6)))


def kuyruk_bekleme(lam):
    if lam >= MU:
        return None
    return lam / (MU * (MU - lam))


tepe = 1400.0
for isabet in (0.95, 0.92, 0.80, 0.50):
    n = sunucu_sayisi(tepe, isabet)
    print("isabet", isabet, "sunucu", n, "12 saat maliyet", n * SAAT_UCRET * 12)

for lam in (22.5, 36.0, 43.0, 45.0):
    w = kuyruk_bekleme(lam)
    print("varis", lam, "doluluk", round(lam / MU, 2),
          "bekleme", "sonsuz" if w is None else round(w, 3))

import math
from decimal import Decimal as D, ROUND_CEILING

KANALLAR = {"b2b": D("0.00"), "pazaryeri_a": D("0.14"), "pazaryeri_b": D("0.10")}
SATIS_HIZI = {"b2b": 12, "pazaryeri_a": 36, "pazaryeri_b": 18}   # adet/saat
GECIKME_DK = {"b2b": 0, "pazaryeri_a": 5, "pazaryeri_b": 12}


def kanal_fiyati(net_hedef, komisyon):
    fiyat = net_hedef / (1 - komisyon)
    return fiyat.quantize(D("0.01"), rounding=ROUND_CEILING)


def gosterilecek_stok(satilabilir, kanal):
    tampon = math.ceil(SATIS_HIZI[kanal] * GECIKME_DK[kanal] / 60)
    return max(0, satilabilir - tampon), tampon


NET_HEDEF = D("1176.82")   # komisyon sonrasi elde kalmasi gereken tutar
SATILABILIR = 40
for kanal, kom in KANALLAR.items():
    fiyat = kanal_fiyati(NET_HEDEF, kom)
    stok, tampon = gosterilecek_stok(SATILABILIR, kanal)
    net = (fiyat * (1 - kom)).quantize(D("0.01"))
    print(kanal, "fiyat", fiyat, "net", net, "stok", stok, "tampon", tampon)
